import java.util.*;

class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = prices[0]; // cheapest buy so far
        int best = 0;
        for (int i = 0; i < prices.length; i++) {
            best = Math.max(best, prices[i] - minPrice); // sell today
            minPrice = Math.min(minPrice, prices[i]);
        }
        return best;
    }
}

