function maxProfit(prices) {
  // best from the right: track max to the right
  let hi = -1, best = 0;
  for (let i = prices.length - 1; i >= 0; i--) { hi = Math.max(hi, prices[i]); best = Math.max(best, hi - prices[i]); }
  return best;
}
